def _expand(cat):
    return {"title": cat["title"], "sanepid": [], "prodcontrol": [B.get(x, x) for x in cat["pc"]]}


def _parse_num(item_text):
    m = re.match(r"\s*(\d+(?:-\d+)?)\s*\)", item_text or "")
    return m.group(1) if m else None


def find_lab_categories(item_text, is_high=None):
    """Сначала — точная шпаргалка по номеру пункта; если номера нет — подбор по словам."""
    num = _parse_num(item_text)
    if num is not None and is_high is not None:
        ids = MAPPING.get(("high" if is_high else "low", num))
        if ids is not None:
            return [_expand(BY_ID[i]) for i in ids if i in BY_ID]
    t = (item_text or "").lower()
    out = []
    for cat in CATEGORIES:
        if cat["id"] in ("6.2", "6.5", "6.8", "2.5", "2.7", "2.8", "5.3"):
            continue  # эти — только для «Моих объектов» через ключи ниже
        keys = {
            "1.1": ["стационар"], "1.2": ["амбулатор", "поликлиник"], "1.3": ["кров", "донор"],
            "1.4": ["стоматолог"], "1.5": ["лаборатор"], "2.1": ["бассейн", "аквапарк", "бан", "саун"],
            "2.2": ["салон", "косметолог", "парикмахер", "маникюр", "педикюр"],
            "2.3": ["очистн", "канализац"], "2.4": ["водоснабжен", "водопровод", "водоисточник", "водозабор"],
            "3": ["классов опасности", "радиотехнич", "промышленн"], "4": ["радиац", "рентген"],
            "5.1": ["школ", "интернат", "вуз", "ссуз", "колледж", "университет", "образован"],
            "5.2": ["дошкольн", "детский сад", "ясли"], "6.1": ["кондитер", "хлеб", "молокоперерабат", "мясоперерабат", "рыбоперерабат", "птицеперерабат", "мукомольн", "сахар", "соль", "крахмал", "макарон", "чипс", "фасовк", "концентрат", "дрожж", "желатин", "алкогольн", "безалкогольн", "минеральн"],
            "6.3": ["столов", "организованных коллективах"], "6.4": ["ресторан", "более 50 посадочных"],
            "6.6": ["быстрог", "фастфуд", "и менее посадочных"], "6.7": ["оптов", "торговл", "рынок", "магазин"],
            "6.9": ["бортов"], "7.1": ["вагон", "железнодорож", "поезд"], "7.2": ["воздушн", "авиа", "самолет"],
        }.get(cat["id"], [])
        if any(k in t for k in keys):
            out.append(_expand(cat))
    return out